/bin/bash -lc "python - <<'PY'
import os, json, urllib.request, urllib.parse
key=open(os.environ['GALAXY_API_KEY_FILE']).read().strip()
tid='toolshed.g2.bx.psu.edu/repos/goeckslab/phykit_metrics/phykit_metrics/0.2.0+galaxy0'
url='https://usegalaxy.org/api/tools/'+urllib.parse.quote(tid, safe='')+'?io_details=true&tool_help=true'
req=urllib.request.Request(url, headers={'x-api-key':key})
data=json.load(urllib.request.urlopen(req))
# Save compact schema to run_trace for audit.
os.makedirs('/workspace/run_trace', exist_ok=True)
open('/workspace/run_trace/phykit_metrics_tool.json','w').write(json.dumps(data, indent=2))

def summarize(inp, indent=0):
    p='  '*indent
    t=inp.get('type')
    print(f\"{p}{inp.get('name')} type={t} label={inp.get('label')"'!r} value={inp.get('"'value')"'!r}")
    if t=='"'select':
        print(f\"{p} options:\", [(o[0], o[1], o[2] if len(o)>2 else None) for o in inp.get('options',[])])
    if t=='conditional':
        for c in inp.get('cases',[]):
            print(f\"{p} when {c.get('value')}\")
            for ci in c.get('inputs',[]): summarize(ci, indent+1)
    if t=='repeat':
        for ci in inp.get('inputs',[]): summarize(ci, indent+1)

for i in data['inputs']:
    summarize(i)
PY"
